"""The ``stockroom`` command."""

import csv
import io
import json
import os
import re
import sys
from decimal import ROUND_HALF_UP, localcontext

from . import fulfilment, movements as movement_tools
from ._lines import ParseError, to_int, valid_date, valid_order_id, valid_sku
from .catalog import parse_catalog
from .movements import Movement, parse_movements, stock_levels
from .orders import parse_orders
from .pricing import CENT, ZERO, price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | invoice ORDER [--json]\n"
    "  fulfil ORDER DATE | report [--format text|csv|json]"
)


class UsageError(Exception):
    """Something wrong with the command line: exit 2."""


class FileProblem(Exception):
    """A file cannot be read: exit 2."""


class Refused(Exception):
    """A data mistake or a refused request: exit 1."""


# command -> (needs: c=catalog m=movements o=orders, positional count, options)
COMMANDS = {
    "stock": ("cm", (0, 0), ("--json",)),
    "low": ("cm", (0, 0), ("--json",)),
    "history": ("cm", (1, 1), ("--json",)),
    "receive": ("cm", (3, 4), ()),
    "ship": ("cm", (3, 4), ()),
    "quote": ("co", (1, 1), ("--json",)),
    "fulfil": ("cmo", (2, 2), ()),
    "invoice": ("cmo", (1, 1), ("--json",)),
    "report": ("cmo", (0, 0), ("--format",)),
}
RAW_COMMANDS = ("receive", "ship", "fulfil")
FILES = {"c": "catalog.txt", "m": "movements.txt", "o": "orders.txt"}


# ---------------------------------------------------------------- formatting


def money(amount):
    if amount == 0:
        return "0.00"
    with localcontext() as context:  # an amount can exceed the default 28 digits
        context.prec = len(amount.as_tuple().digits) + 4
        return format(amount.quantize(CENT, rounding=ROUND_HALF_UP), "f")


def dump_json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def signed(quantity):
    return "%+d" % quantity


def movement_line(move):
    line = "%s %s %s" % (move.date.isoformat(), move.sku, signed(move.quantity))
    return line + " " + move.note if move.note else line


# ------------------------------------------------------------- command line


def split_dir(args):
    """Pull every ``--dir`` out of ``args``; return (dir or None, the rest)."""
    directory = None
    rest = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--dir":
            if i + 1 >= len(args):
                raise UsageError("--dir needs a value")
            directory = args[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    return directory, rest


def parse_command_line(args):
    """Return (command, positionals, options)."""
    if not args:
        raise UsageError("no command given")
    command, tokens = args[0], args[1:]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    _, (low, high), allowed = COMMANDS[command]
    positionals = []
    options = {}
    if command in RAW_COMMANDS:
        positionals = list(tokens)
    else:
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == "--json" and "--json" in allowed:
                options["json"] = True
            elif token == "--format" and "--format" in allowed:
                if i + 1 >= len(tokens):
                    raise UsageError("--format needs a value")
                options["format"] = tokens[i + 1]
                i += 1
            elif token.startswith("--format=") and "--format" in allowed:
                options["format"] = token[len("--format="):]
            elif token.startswith("-") and len(token) > 1:
                raise UsageError("unknown option %r" % token)
            else:
                positionals.append(token)
            i += 1
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)
    if "format" in options and options["format"] not in ("text", "csv", "json"):
        raise UsageError("bad --format value %r (text, csv or json)" % options["format"])
    dates = {"receive": 0, "ship": 0, "fulfil": 1}
    if command in dates and valid_date(positionals[dates[command]]) is None:
        raise UsageError("bad date %r (use YYYY-MM-DD)" % positionals[dates[command]])
    return command, positionals, options


# -------------------------------------------------------------------- files


def read_files(directory, needs):
    if not os.path.isdir(directory):
        raise FileProblem("%s: not a folder" % directory)
    texts = {}
    for key in needs:
        name = FILES[key]
        path = os.path.join(directory, name)
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if key == "c":
                raise FileProblem("%s: no such file" % name)
            texts[key] = ""
            continue
        except OSError as error:
            raise FileProblem("%s: %s" % (name, error.strerror or error))
        try:
            texts[key] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise FileProblem("%s: not valid UTF-8" % name)
    return texts


def parse_files(texts):
    data = {}
    steps = (
        ("c", lambda: parse_catalog(texts["c"])),
        ("m", lambda: parse_movements(texts["m"], data["c"])),
        ("o", lambda: parse_orders(texts["o"], data["c"])),
    )
    for key, step in steps:
        if key not in texts:
            continue
        try:
            data[key] = step()
        except ParseError as error:
            raise Refused("%s: %s" % (FILES[key], error))
    return data


def append_movements(directory, moves):
    path = os.path.join(directory, FILES["m"])
    prefix = ""
    try:
        if os.path.exists(path) and os.path.getsize(path) > 0:
            with open(path, "rb") as handle:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = "\n"
        payload = (prefix + "".join(movement_line(m) + "\n" for m in moves)).encode("utf-8")
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as error:
        raise FileProblem("%s: %s" % (FILES["m"], error.strerror or error))


# ----------------------------------------------------------------- commands


def stock_status(product, onhand):
    if onhand == 0:
        return "out"
    return "low" if onhand <= product.reorder else "ok"


def cmd_stock(data, positionals, options):
    levels = stock_levels(data["c"], data["m"])
    rows = []
    for sku in sorted(data["c"]):
        product = data["c"][sku]
        rows.append((sku, levels[sku], stock_status(product, levels[sku]), product.name))
    if options.get("json"):
        return dump_json(
            [{"sku": s, "name": n, "onhand": q, "status": st} for s, q, st, n in rows]
        )
    return "".join("%s %d %s %s\n" % row for row in rows)


def cmd_low(data, positionals, options):
    levels = stock_levels(data["c"], data["m"])
    rows = []
    for sku in sorted(data["c"]):
        product = data["c"][sku]
        if stock_status(product, levels[sku]) != "ok":
            buy = max(1, 2 * product.reorder - levels[sku])
            rows.append((sku, levels[sku], product.reorder, buy))
    if options.get("json"):
        return dump_json(
            [{"sku": s, "onhand": q, "reorder": r, "buy": b} for s, q, r, b in rows]
        )
    return "".join("%s %d %d %d\n" % row for row in rows)


def cmd_history(data, positionals, options):
    sku = valid_sku(positionals[0])
    if sku is None or sku not in data["c"]:
        raise Refused("unknown SKU %r" % positionals[0])
    rows = movement_tools.history(data["m"], sku)
    if options.get("json"):
        return dump_json(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": signed(m.quantity),
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    out = []
    for m, balance in rows:
        line = "%s %s %d" % (m.date.isoformat(), signed(m.quantity), balance)
        out.append(line + " " + m.note + "\n" if m.note else line + "\n")
    return "".join(out)


def record_movement(directory, data, positionals, direction):
    for text in positionals:
        try:
            text.encode("utf-8")
        except UnicodeEncodeError:
            raise UsageError("argument %r is not valid UTF-8" % text)
    date = valid_date(positionals[0])
    sku = valid_sku(positionals[1])
    if sku is None or sku not in data["c"]:
        raise Refused("unknown SKU %r" % positionals[1])
    raw = positionals[2]
    quantity = to_int(raw) if re.fullmatch(r"[0-9]+", raw) else None
    if not quantity:
        raise Refused("bad quantity %r (a whole number of one or more)" % raw)
    note = positionals[3].strip() if len(positionals) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    move = Movement(date, sku, direction * quantity, note)
    if movement_tools.first_below_zero(data["m"] + [move]) is not None:
        raise Refused("stock of %s would go below zero" % sku)
    append_movements(directory, [move])
    return movement_line(move) + "\n"


def quote_object(order, quote):
    return {
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit": money(line.unit),
                "gross": money(line.gross),
                "discount": money(line.discount),
                "net": money(line.net),
            }
            for line in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


def quote_text(order, quote, prefix=""):
    out = ["%s%s %s %s\n" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s\n"
            % (
                line.sku,
                line.quantity,
                money(line.unit),
                money(line.gross),
                money(line.discount),
                money(line.net),
            )
        )
    out.append("subtotal %s\n" % money(quote.subtotal))
    out.append("order discount %s\n" % money(quote.order_discount))
    out.append("tax %s\n" % money(quote.tax))
    out.append("total %s\n" % money(quote.total))
    return "".join(out)


def find_order(data, text):
    wanted = valid_order_id(text)
    for order in data["o"]:
        if order.id == wanted:
            return order
    raise Refused("unknown order %r" % text)


def cmd_quote(data, positionals, options):
    order = find_order(data, positionals[0])
    quote = price_order(order, data["c"])
    if options.get("json"):
        return dump_json(quote_object(order, quote))
    return quote_text(order, quote)


def cmd_invoice(data, positionals, options):
    order = find_order(data, positionals[0])
    shipped = fulfilment.shipped_so_far(order, data["m"])
    billed = fulfilment.shipped_order(order, shipped)
    if not billed.lines:
        raise Refused("nothing has shipped on order %s" % order.id)
    quote = price_order(billed, data["c"])
    if options.get("json"):
        return dump_json(quote_object(order, quote))
    return quote_text(order, quote, prefix="invoice ")


def cmd_fulfil(directory, data, positionals):
    order = find_order(data, positionals[0])
    date = valid_date(positionals[1])
    if date < order.date:
        raise Refused("%s is before the order date %s" % (positionals[1], order.date.isoformat()))
    shipped = fulfilment.shipped_so_far(order, data["m"])
    new_moves = []
    out = []
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        send = min(owed, fulfilment.available_on(data["m"], sku, date))
        if send > 0:
            new_moves.append(Movement(date, sku, -send, "order " + order.id))
            shipped[sku] += send
        out.append("%s shipped %d backordered %d\n" % (sku, send, owed - send))
    if new_moves:
        append_movements(directory, new_moves)
    out.append("status %s\n" % fulfilment.status(order, shipped))
    return "".join(out)


def sort_key(order):
    digits = order.id[3:].lstrip("0")  # numeric order without int(): shorter is smaller
    return (order.date, len(digits), digits, order.id)


def cmd_report(data, positionals, options):
    rows = []
    for order in sorted(data["o"], key=sort_key):
        shipped = fulfilment.shipped_so_far(order, data["m"])
        billed = fulfilment.shipped_order(order, shipped)
        quoted = price_order(order, data["c"]).total
        invoiced = price_order(billed, data["c"]).total if billed.lines else ZERO
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": fulfilment.status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped.values()),
                "quoted": money(quoted),
                "invoiced": money(invoiced),
            }
        )
    form = options.get("format", "text")
    if form == "json":
        return dump_json(rows)
    if form == "csv":
        buffer = io.StringIO()
        writer = csv.DictWriter(buffer, list(rows[0]) if rows else CSV_COLUMNS, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n"
        % (
            r["order"],
            r["date"],
            r["customer"],
            r["status"],
            r["shipped"],
            r["ordered"],
            r["quoted"],
            r["invoiced"],
        )
        for r in rows
    )


CSV_COLUMNS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def run(argv):
    """Carry out one command line; return the text for standard output."""
    directory, rest = split_dir(argv)
    command, positionals, options = parse_command_line(rest)
    directory = "." if directory is None else directory
    texts = read_files(directory, COMMANDS[command][0])
    data = parse_files(texts)
    if command == "stock":
        return cmd_stock(data, positionals, options)
    if command == "low":
        return cmd_low(data, positionals, options)
    if command == "history":
        return cmd_history(data, positionals, options)
    if command == "receive":
        return record_movement(directory, data, positionals, +1)
    if command == "ship":
        return record_movement(directory, data, positionals, -1)
    if command == "quote":
        return cmd_quote(data, positionals, options)
    if command == "invoice":
        return cmd_invoice(data, positionals, options)
    if command == "fulfil":
        return cmd_fulfil(directory, data, positionals)
    return cmd_report(data, positionals, options)


def _write_stdout(text):
    data = text.encode("utf-8")
    stream = getattr(sys.stdout, "buffer", None)
    if stream is not None:
        stream.write(data)
    else:
        sys.stdout.write(text)
    sys.stdout.flush()


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        output = run(argv)
    except UsageError as error:
        sys.stderr.write("stockroom: %s\n%s\n" % (error, USAGE))
        return 2
    except FileProblem as error:
        sys.stderr.write("stockroom: %s\n" % error)
        return 2
    except Refused as error:
        sys.stderr.write("stockroom: %s\n" % error)
        return 1
    try:
        _write_stdout(output)
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
    return 0
