def split_dir(args):
    """Pull every ``--dir`` out of ``args``; return (dir or None, the rest)."""
    directory = None
    rest = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--dir":
            if i + 1 >= len(args):
                raise UsageError("--dir needs a value")
            directory = args[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    return directory, rest


def parse_command_line(args):
    """Return (command, positionals, options)."""
    if not args:
        raise UsageError("no command given")
    command, tokens = args[0], args[1:]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    _, (low, high), allowed = COMMANDS[command]
    positionals = []
    options = {}
    if command in RAW_COMMANDS:
        positionals = list(tokens)
    else:
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == "--json" and "--json" in allowed:
                options["json"] = True
            elif token == "--format" and "--format" in allowed:
                if i + 1 >= len(tokens):
                    raise UsageError("--format needs a value")
                options["format"] = tokens[i + 1]
                i += 1
            elif token.startswith("--format=") and "--format" in allowed:
                options["format"] = token[len("--format="):]
            elif token.startswith("-") and len(token) > 1:
                raise UsageError("unknown option %r" % token)
            else:
                positionals.append(token)
            i += 1
